CountDownLatch wszyscyObsluzeni = new CountDownLatch(LICZBA_KLIENTOW);

for (int i = 1; i <= LICZBA_KLIENTOW; i++) {
    Socket klient = serverSocket.accept();
    Thread t = new Thread(() -> obsluzKlienta(klient, wszyscyObsluzeni));
    t.setDaemon(true);
    t.start();
}

wszyscyObsluzeni.await(5, TimeUnit.SECONDS);
// W realnym serwerze petla accept() jest NIESKONCZONA. W lekcji ograniczamy ja
// do stalej, znanej z gory liczby klientow (LICZBA_KLIENTOW), a CountDownLatch
// pozwala poczekac na zakonczenie WSZYSTKICH watkow obslugi bez zgadywania
// czasu przez sleep - demo zawsze konczy sie samo.
